// HTTP contract of the SoterCare API and of the mock notifier.

import ballerina/http;

public type AcceptedBody readonly & record {|
    string eventId;
    string status;
    CareSeverity severity;
    string routedTo;
    boolean notified;
    string correlationId;
|};

public type ErrorBody readonly & record {|
    string code;
    string message;
    string correlationId;
|};

public type AcceptedResponse record {|
    *http:Accepted;
    AcceptedBody body;
|};

public type ConflictResponse record {|
    *http:Conflict;
    ErrorBody body;
|};

public type BadRequestResponse record {|
    *http:BadRequest;
    ErrorBody body;
|};

public type ServiceUnavailableResponse record {|
    *http:ServiceUnavailable;
    ErrorBody body;
|};

// Wire format produced by sanjulaonline/resilient_event_router. The mock notifier
// binds to it directly, which is also a check that the envelope is stable.
public type EventEnvelope record {|
    string id;
    string eventType;
    string severity;
    map<string> metadata;
    json payload;
|};

public type NotificationReceipt readonly & record {|
    string notificationId;
    string status;
    int attempt;
|};

public type NotifierAcceptedResponse record {|
    *http:Accepted;
    NotificationReceipt body;
|};

public type NotifierErrorResponse record {|
    *http:InternalServerError;
    ErrorBody body;
|};

public type AttemptCount readonly & record {|
    string eventId;
    int attempts;
|};

// SoterCare domain layer.
//
// Everything in this file answers "what does this event mean?". Nothing here
// knows how the event is delivered; that is the job of the
// sanjulaonline/resilient_event_router package.

import sanjulaonline/resilient_event_router as router;

// Clinical-style severity used by the SoterCare API. It is intentionally finer
// grained than the router's transport severity, which is the point of keeping
// the two layers apart.
public type CareSeverity "normal"|"medium"|"high"|"critical";

// Named routes used by the SoterCare API and by the routing rule below.
public const string ROUTE_EVENT_LOG = "event-log";
public const string ROUTE_CAREGIVER = "caregiver-notifier";

public type SensorEvent readonly & record {|
    string eventId;
    string deviceId;
    string eventType;
    float value;
    string unit;
    int timestamp;
|};

public type CareDecision readonly & record {|
    CareSeverity severity;
    string routedTo;
    string reason;
|};

// Synthetic thresholds for a prototype. They have not been clinically
// reviewed and must not be used to detect, diagnose or treat anything.
public isolated function validateAndClassify(SensorEvent event) returns CareDecision|error {
    if event.eventId.length() < 4 {
        return error("eventId must contain at least four characters");
    }
    if event.deviceId.length() < 3 {
        return error("deviceId must contain at least three characters");
    }
    if event.timestamp <= 0 {
        return error("timestamp must be a positive Unix timestamp");
    }

    match event.eventType {
        "fall" => {
            if event.unit != "boolean" || (event.value != 0.0 && event.value != 1.0) {
                return error("fall events require unit 'boolean' and value 0.0 or 1.0");
            }
            if event.value == 1.0 {
                return {severity: "critical", routedTo: ROUTE_CAREGIVER, reason: "fall detected"};
            }
            return {severity: "normal", routedTo: ROUTE_EVENT_LOG, reason: "no fall detected"};
        }
        "vitals" => {
            if event.unit != "bpm" || event.value < 30.0 || event.value > 240.0 {
                return error("vitals events require unit 'bpm' and a value from 30.0 to 240.0");
            }
            if event.value < 50.0 || event.value > 120.0 {
                return {
                    severity: "high",
                    routedTo: ROUTE_CAREGIVER,
                    reason: "heart rate outside the prototype threshold"
                };
            }
            return {
                severity: "normal",
                routedTo: ROUTE_EVENT_LOG,
                reason: "heart rate inside the prototype threshold"
            };
        }
        "moisture" => {
            if event.unit != "percent" || event.value < 0.0 || event.value > 100.0 {
                return error("moisture events require unit 'percent' and a value from 0.0 to 100.0");
            }
            if event.value >= 80.0 {
                return {
                    severity: "medium",
                    routedTo: ROUTE_EVENT_LOG,
                    reason: "moisture crossed the prototype threshold"
                };
            }
            return {
                severity: "normal",
                routedTo: ROUTE_EVENT_LOG,
                reason: "moisture inside the prototype threshold"
            };
        }
        _ => {
            return error("unsupported eventType; use fall, vitals, or moisture");
        }
    }
}

// Maps the four SoterCare severities onto the three transport severities the
// router understands.
public isolated function toRouterSeverity(CareSeverity severity) returns router:Severity {
    match severity {
        "critical" => {
            return router:CRITICAL;
        }
        "high"|"medium" => {
            return router:WARNING;
        }
        _ => {
            return router:INFO;
        }
    }
}

// Builds the domain-neutral event handed to the router. The SoterCare routing
// choice travels as metadata so the routing rule stays a pure function of the
// generic event.
public isolated function toRouterEvent(SensorEvent event, CareDecision decision) returns router:Event => {
    id: event.eventId,
    eventType: "sensor." + event.eventType,
    payload: {
        deviceId: event.deviceId,
        value: event.value,
        unit: event.unit,
        timestamp: event.timestamp,
        reason: decision.reason
    },
    metadata: {
        route: decision.routedTo,
        careSeverity: decision.severity
    }
};

// Only caregiver-bound events leave the process. Everything else is recorded
// locally, which the router reports as delivered: false.
public isolated function routeByCareDecision(router:Event event, router:Severity severity) returns string? {
    string route = event.metadata["route"] ?: ROUTE_EVENT_LOG;
    return route == ROUTE_CAREGIVER ? router:DEFAULT_DESTINATION : ();
}

// Deliberately unreliable downstream notifier.
//
// It is part of the example so the failure paths are reproducible without an
// external account or real data. Event ids beginning with "fail-" always
// return HTTP 500.

import ballerina/http;

configurable int notifierPort = 9091;

isolated map<int> notifierAttempts = {};

isolated function nextNotifierAttempt(string eventId) returns int {
    lock {
        int next = (notifierAttempts[eventId] ?: 0) + 1;
        notifierAttempts[eventId] = next;
        return next;
    }
}

public isolated function getNotifierAttempts(string eventId) returns int {
    lock {
        return notifierAttempts[eventId] ?: 0;
    }
}

public isolated function resetPrototypeState() {
    lock {
        notifierAttempts.removeAll();
    }
}

service /notifier on new http:Listener(notifierPort) {

    isolated resource function post alerts(EventEnvelope envelope)
            returns NotifierAcceptedResponse|NotifierErrorResponse {
        int attempt = nextNotifierAttempt(envelope.id);

        if envelope.id.startsWith("fail-") {
            NotifierErrorResponse failure = {
                body: {
                    code: "SIMULATED_NOTIFIER_FAILURE",
                    message: "synthetic downstream failure",
                    correlationId: envelope.id
                }
            };
            return failure;
        }

        NotifierAcceptedResponse accepted = {
            body: {
                notificationId: "notification-" + envelope.id,
                status: "delivered",
                attempt
            }
        };
        return accepted;
    }

    isolated resource function get attempts/[string eventId]() returns AttemptCount {
        return {eventId, attempts: getNotifierAttempts(eventId)};
    }
}

// SoterCare API.
//
// The resource validates and classifies the sensor reading, then hands a
// domain-neutral event to the router. Duplicate suppression, the outbound
// timeout, transport retries, backoff and circuit breaking all live in
// sanjulaonline/resilient_event_router.

import ballerina/http;
import ballerina/log;

import sanjulaonline/resilient_event_router as router;

configurable int servicePort = 9090;
configurable string notifierBaseUrl = "http://localhost:9091";

final router:Router eventRouter = check new ({
    destinationUrl: notifierBaseUrl + "/notifier/alerts",
    routingRule: routeByCareDecision,
    timeout: 1,
    transportRetry: {count: 2, interval: 0.05, backOffFactor: 2.0, maxWaitInterval: 0.2},
    circuitBreaker: {
        timeWindow: 10,
        bucketSize: 2,
        requestVolumeThreshold: 10,
        failureThreshold: 0.5,
        resetTime: 2,
        statusCodes: [500, 502, 503]
    }
});

service /api/v1 on new http:Listener(servicePort) {

    isolated resource function get health() returns record {|string status; string serviceName;|} {
        return {status: "UP", serviceName: "sotercare-alert-router"};
    }

    isolated resource function post events(SensorEvent event)
            returns AcceptedResponse|ConflictResponse|BadRequestResponse|ServiceUnavailableResponse {
        string correlationId = event.eventId;

        CareDecision|error decision = validateAndClassify(event);
        if decision is error {
            BadRequestResponse response = {
                body: {code: "INVALID_EVENT", message: decision.message(), correlationId}
            };
            return response;
        }

        router:RouteResult|router:RouterError result =
            eventRouter.route(toRouterEvent(event, decision), toRouterSeverity(decision.severity));

        if result is router:DuplicateEventError {
            ConflictResponse response = {
                body: {
                    code: "DUPLICATE_EVENT",
                    message: "eventId has already been processed",
                    correlationId
                }
            };
            return response;
        }

        if result is router:RouterError {
            log:printError("caregiver notification failed", eventId = event.eventId,
                    deviceId = event.deviceId, failure = deliveryFailureKind(result),
                    reason = result.message());
            ServiceUnavailableResponse response = {
                body: {
                    code: "NOTIFIER_UNAVAILABLE",
                    message: "event was not marked as processed; retry with the same eventId",
                    correlationId
                }
            };
            return response;
        }

        log:printInfo("sensor event accepted", eventId = event.eventId, severity = decision.severity,
                routedTo = decision.routedTo, notified = result.delivered);
        AcceptedResponse response = {
            body: {
                eventId: event.eventId,
                status: "accepted",
                severity: decision.severity,
                routedTo: decision.routedTo,
                notified: result.delivered,
                correlationId
            }
        };
        return response;
    }
}

// The HTTP contract stays a single 503 so the published API does not change,
// but the typed router error is recorded so operators can tell the cases apart.
isolated function deliveryFailureKind(router:RouterError err) returns string {
    if err is router:CircuitOpenError {
        return "circuit-open";
    }
    if err is router:TransportError {
        return "transport";
    }
    if err is router:DownstreamError {
        return "downstream-status";
    }
    if err is router:InvalidDestinationError {
        return "invalid-destination";
    }
    return "unknown";
}
